func isLocalMessageType(t pb.MessageType) bool {
	return t == pb.Election ||
		t == pb.LeaderHeartbeat ||
		t == pb.Unreachable ||
		t == pb.SnapshotStatus ||
		t == pb.CheckQuorum ||
		t == pb.LocalTick ||
		t == pb.BatchedReadIndex
}

